// Sincronización inicial tienda → back-office · Stock «de antes de los pedidos».
// El back-office descuenta stock al recibir cada pedido, y el stock de la tienda YA tiene descontados
// esos pedidos. Por eso se carga primero stock + unidades de los pedidos (así ningún pedido se rechaza
// por falta de stock) y, al final, el stock real de la tienda.
const orders = $('Tienda: pedidos').first().json.orders;
const catalog = $('Tienda: catálogo').first().json.products;
const exec = 'n8n_sync_' + $execution.id;

const units = {};
for (const o of orders) {
  for (const l of o.data.lines) units[l.product_code] = (units[l.product_code] || 0) + l.quantity;
}
const known = new Set(catalog.map(p => p.sku));

return [{ json: {
  orders_count: orders.length,
  unknown_skus: Object.keys(units).filter(sku => !known.has(sku)),
  import_pre: { execution_id: exec + '_stock_previo', products: catalog.map(p => ({ ...p, stock_available: p.stock_available + (units[p.sku] || 0) })) },
  import_final: { execution_id: exec + '_stock_real', products: catalog },
} }];

// Un item por pedido, en el formato de POST /api/v1/webhooks/orders (misma tabla que el escenario 1).
// event_id fijo por pedido («sync-PQ-…»): si el flujo se ejecuta otra vez, el back-office responde «duplicate».
// occurred_at = fecha real del pedido, para que el histórico por día del cuadro de mando sea correcto.
const orders = $('Tienda: pedidos').first().json.orders;
const exec = 'n8n_sync_' + $execution.id;

return orders.map(o => {
  const d = o.data;
  const ord = d.order;
  const a = d.shipping_address;
  return { json: { reference: o.reference, payload: {
    event_id: 'sync-' + o.reference,
    execution_id: exec,
    event_type: 'order.synced',
    occurred_at: o.created_at,
    order_ref: ord.reference,
    status: ord.status,                        // estado actual del pedido (enviado, cancelado…)
    payment_method: o.payment_method,          // redsys_sandbox, transferencia_simulada o null
    shipping_address: `${a.address}, ${a.postal_code} ${a.city} (${a.country})`,
    customer: { name: d.customer.name, email: d.customer.email },
    items: d.lines.map(l => ({
      sku: l.product_code,
      product_name: l.name,
      variant_size: l.size,
      quantity: l.quantity,
      unit_price: l.unit_price,
    })),
    discount_code: ord.discount_code,
    discount_amount: ord.discount,
    shipping_amount: ord.shipping,
    total_amount: ord.total,
  } } };
});

// Resultado de cada pedido (la salida del HTTP va en el mismo orden que los pedidos enviados)
const sent = $('Pedidos uno a uno').all();
const results = $input.all().map((it, i) => ({
  reference: sent[i]?.json.reference ?? null,
  http: it.json.statusCode ?? null,
  result: it.json.body?.result ?? null,
  error_code: it.json.body?.error_code ?? (it.json.error ? 'SIN_RESPUESTA' : null),
  message: it.json.body?.message ?? it.json.error?.message ?? null,
}));
const byResult = {};
for (const r of results) {
  const k = r.result || r.error_code || 'error';
  byResult[k] = (byResult[k] || 0) + 1;
}
return [{ json: { pedidos: results.length, por_resultado: byResult, rechazados: results.filter(r => r.http !== 200) } }];

// Resumen de la sincronización
const prep = $('Preparar carga').first().json;
const resumen = $('Resumen de pedidos').first().json;
const pre = $('Back-office: stock previo').first().json;
const fin = $input.first().json;

return [{ json: {
  pedidos_enviados: resumen.pedidos,
  pedidos_por_resultado: resumen.por_resultado,
  pedidos_rechazados: resumen.rechazados,
  skus_de_pedidos_que_no_estan_en_el_catalogo: prep.unknown_skus,
  stock_previo: pre.message,
  stock_real: fin.message,
  stock_cuadrado_con_la_tienda: fin.ok === true,
  nota: fin.updated === 0
    ? 'Tras cargar los pedidos, el stock del back-office ya coincidía con el de la tienda.'
    : `Se corrigieron ${fin.updated} referencias (pedidos ignorados o rechazados): ahora coinciden con la tienda.`,
} }];
